    std::shared_ptr<Session> tgt_;
    std::shared_ptr<std::atomic<bool>> live_;   // shared with the grantor's revoker
public:
    void write(std::span<const char> b) override {
        if (!live_->load(std::memory_order_acquire)) throw Revoked{};
        tgt_->write(b);
    }
};
