class SessionFwd : public Session {
    std::weak_ptr<Session> grant_;              // no strong reference here
public:
    void write(std::span<const char> b) override {
        auto t = grant_.lock();                 // empty once the grant is dropped
        if (!t) throw Revoked{};
        t->write(b);
    }
};
// grantor: strong_.reset();  -- everything handed out stops working

class SessionFwd : public Session {
    std::shared_mutex m_;
    Session* t_; bool live_ = true;
public:
    void write(std::span<const char> b) override {
        std::shared_lock g(m_);                  // many calls in parallel
        if (!live_) throw Revoked{};
        t_->write(b);
    }
    void revoke() { std::unique_lock g(m_); live_ = false; }  // waits for in-flight calls
};
